INSERT INTO claims (claim_id, claim_text, correct_answer, answer_rationale, overall_stance, summary, origin_outlet, origin_author, origin_first_seen_at, origin_url, study_set, study_position) VALUES ('claim_46', 'MSG in food causes headaches.', 'misleading', 'Only at large doses without food in some sensitive people.', 'mixed', 'The FDA says it could never confirm that MSG caused reported symptoms. Mild, short-term symptoms appeared only in some sensitive people taking 3 grams or more without food, while a normal serving has under 0.5 grams.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO sources (source_id, title, outlet, author, published_at, url, source_type) VALUES ('src_46a', 'Questions and Answers on Monosodium glutamate (MSG)', 'U.S. Food and Drug Administration', NULL, NULL, 'https://www.fda.gov/food/food-additives-petitions/questions-and-answers-monosodium-glutamate-msg?p=18562', 'official');
