INSERT INTO claims (claim_id, claim_text, correct_answer, answer_rationale, overall_stance, summary, origin_outlet, origin_author, origin_first_seen_at, origin_url, study_set, study_position) VALUES ('claim_47', 'Microwaving food destroys its nutrients.', 'misleading', 'Some loss happens with all cooking; microwaving is often gentler.', 'mixed', 'All cooking causes some nutrient loss. Because microwaving is quick and uses little water, it is one of the methods least likely to destroy nutrients.', NULL, NULL, NULL, NULL, NULL, NULL);
