INSERT INTO claims (claim_id, claim_text, correct_answer, answer_rationale, overall_stance, summary, origin_outlet, origin_author, origin_first_seen_at, origin_url, study_set, study_position) VALUES ('claim_48', 'Humans share 60 percent of their DNA with bananas.', 'misleading', '60% refers to genes with counterparts, not identical DNA.', 'mixed', 'About 60 percent of human genes have a counterpart in bananas, but genes are only a small part of our DNA, so the shared portion of the whole genome is far smaller.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO sources (source_id, title, outlet, author, published_at, url, source_type) VALUES ('src_48a', 'QuickCheck: Do humans share 60% of our DNA with bananas?', 'The Star', 'Hee May Yee', '2025-11-05', 'https://www.thestar.com.my/news/true-or-not/2025/11/05/quickcheck-do-humans-share-60-of-our-dna-with-bananas', 'fact_check');
