INSERT INTO evidence (evidence_id, claim_id, source_id, summary, stance, display_order) VALUES ('ev_48a', 'claim_48', 'src_48a', 'Humans share roughly 60% of genes with bananas, which is only about 1 to 2% of the human genome.', 'context', 0);
