INSERT INTO claim_sources (claim_id, source_id, is_primary, display_order) VALUES ('claim_48', 'src_48b', FALSE, 1);
INSERT INTO evidence (evidence_id, claim_id, source_id, summary, stance, display_order) VALUES ('ev_48b', 'claim_48', 'src_48b', 'Rated false: the shared figure is about genes with matching functions, not identical DNA.', 'contradicts', 1);
